static inline void oss_normalizza(const float *grezza, float *fuori)
{
    for (int i = 0; i < OSS_N; ++i) {
        float v = (grezza[i] - oss_media[i]) * oss_inv_scala[i];
        if (v >  OSS_CLIP) v =  OSS_CLIP;
        if (v < -OSS_CLIP) v = -OSS_CLIP;
        fuori[i] = v;
    }
}
